package com.lercs;

import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.data.domain.*;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.http.*;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.authentication.*;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.transaction.annotation.Transactional;
import java.io.IOException;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;

record ApiResponse<T>(boolean success,String message,T data) { static <T> ApiResponse<T> ok(String m,T d){return new ApiResponse<>(true,m,d);} }
record ErrorResponse(boolean success,String message,Map<String,String> errors,Instant timestamp) {}
record RegisterRequest(@NotBlank @Email String email,@NotBlank @Size(min=8,max=100) String password,@NotBlank @Size(max=120) String fullName,@Size(max=30) String phone,Role role) {}
record ProfileRequest(@NotBlank @Size(max=120) String fullName,@Size(max=30) String phone) {}
record CategoryRequest(@NotBlank @Size(max=100) String name) {}
record LoginRequest(@NotBlank @Email String email,@NotBlank String password) {}
record UserView(Long id,String email,String fullName,String phone,Role role,boolean active,Instant createdAt) { static UserView from(User u){return new UserView(u.id,u.email,u.fullName,u.phone,u.role,u.active,u.createdAt);} }
record TokenView(String token,UserView user) {}
record EmergencyRequest(@NotNull Long categoryId,@NotBlank @Size(max=180) String title,@NotBlank @Size(max=3000) String description,Priority priority,@Min(0) int peopleAffected,@NotBlank String address,String city,String state,String postalCode,@DecimalMin("-90") @DecimalMax("90") Double latitude,@DecimalMin("-180") @DecimalMax("180") Double longitude,String assistance,@Size(max=100) String evidenceFileName) {}
record StatusRequest(@NotNull EmergencyStatus status,@Size(max=500) String comment) {}
record ResourceRequest(@NotBlank String name,@NotBlank String category,String description,@Min(0) int quantity,@NotBlank String unit,String location) {}
record AssignResourceRequest(@NotNull Long emergencyId,@Min(1) int quantity,String notes) {}
record AssignResponderRequest(@NotNull Long emergencyId,@NotNull Long responderProfileId,String notes) {}
record AssignmentStatusRequest(@NotNull AssignmentStatus status,String notes) {}
record ResponderRequest(@Size(max=1000) String skills,String experience,Availability availability,Double latitude,Double longitude) {}
record ShelterRequest(@NotBlank String name,@NotBlank String address,String city,String state,String contactNumber,Double latitude,Double longitude,@Min(1) int capacity,@Min(0) int occupiedCapacity,String facilities,String accessibility,FacilityStatus status) {}
record HospitalRequest(@NotBlank String name,@NotBlank String address,String city,String phone,Double latitude,Double longitude,boolean emergencyAvailable,@Min(0) int bedCapacity,@Min(0) int availableBeds,boolean ambulanceAvailable,String services,FacilityStatus status) {}
record AnnouncementRequest(@NotBlank String title,@NotBlank @Size(max=3000) String message,Priority priority,@jakarta.validation.constraints.Pattern(regexp="ALL|CITIZENS|RESPONDERS|COORDINATORS|ADMINS") String targetAudience,Instant expiryAt,Boolean active) {}
record PageView<T>(List<T> items,int page,int size,long totalElements,int totalPages) { static <T> PageView<T> from(Page<T> p){return new PageView<>(p.getContent(),p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages());} }

@RestControllerAdvice
class Errors {
 @ExceptionHandler(ResponseStatusException.class) ResponseEntity<ErrorResponse> status(ResponseStatusException e){return ResponseEntity.status(e.getStatusCode()).body(new ErrorResponse(false,e.getReason(),Map.of(),Instant.now()));}
 @ExceptionHandler(org.springframework.web.bind.MethodArgumentNotValidException.class) ResponseEntity<ErrorResponse> validation(org.springframework.web.bind.MethodArgumentNotValidException e){Map<String,String> m=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->m.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(new ErrorResponse(false,"Validation failed",m,Instant.now()));}
 @ExceptionHandler(AccessDeniedException.class) ResponseEntity<ErrorResponse> forbidden(AccessDeniedException e){return ResponseEntity.status(403).body(new ErrorResponse(false,"Access denied",Map.of(),Instant.now()));}
 @ExceptionHandler({IllegalArgumentException.class,org.springframework.dao.DataIntegrityViolationException.class}) ResponseEntity<ErrorResponse> bad(RuntimeException e){return ResponseEntity.badRequest().body(new ErrorResponse(false,e instanceof IllegalArgumentException?e.getMessage():"The request conflicts with existing data",Map.of(),Instant.now()));}
 @ExceptionHandler(Exception.class) ResponseEntity<ErrorResponse> generic(Exception e){e.printStackTrace();return ResponseEntity.internalServerError().body(new ErrorResponse(false,e.getMessage()!=null&&!e.getMessage().isBlank()?e.getMessage():"An unexpected error occurred",Map.of(),Instant.now()));}
}

@RestController @RequestMapping("/api/auth")
class AuthController {
 private final Users users; private final BCryptPasswordEncoder encoder; private final JwtService jwt;
 AuthController(Users u,BCryptPasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}
 @PostMapping("/register") ResponseEntity<ApiResponse<UserView>> register(@Valid @RequestBody RegisterRequest r){if(users.findByEmail(r.email()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email is already registered");Role role=r.role()==Role.RESPONDER?Role.RESPONDER:Role.CITIZEN;User u=users.save(new User(r.email().toLowerCase(),encoder.encode(r.password()),r.fullName(),r.phone(),role));return ResponseEntity.status(201).body(ApiResponse.ok("Account created",UserView.from(u)));}
 @PostMapping("/login") TokenView login(@Valid @RequestBody LoginRequest r){User u=users.findByEmail(r.email().toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!u.active||!encoder.matches(r.password(),u.password))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return new TokenView(jwt.create(u),UserView.from(u));}
 @GetMapping("/me") UserView me(){return UserView.from(currentUser(users));}
 @PutMapping("/profile") ApiResponse<UserView> updateProfile(@Valid @RequestBody ProfileRequest request){User user=currentUser(users);user.fullName=request.fullName();user.phone=request.phone();return ApiResponse.ok("Profile updated",UserView.from(users.save(user)));}
 static User currentUser(Users repo){String email=SecurityContextHolder.getContext().getAuthentication().getName();return repo.findByEmail(email).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"User session is invalid"));}
}

@RestController @RequestMapping("/api/categories")
class CategoryController {
 private final Categories categories;private final Users users;CategoryController(Categories categories,Users users){this.categories=categories;this.users=users;}
 @GetMapping List<EmergencyCategory> list(){return categories.findAll().stream().filter(c->c.active).toList();}
 @PostMapping ResponseEntity<ApiResponse<EmergencyCategory>> create(@Valid @RequestBody CategoryRequest request){User actor=AuthController.currentUser(users);if(actor.role!=Role.ADMIN)throw new AccessDeniedException("Admin role required");if(categories.findByName(request.name()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Category already exists");return ResponseEntity.status(201).body(ApiResponse.ok("Category created",categories.save(new EmergencyCategory(request.name()))));}
 @PutMapping("/{id}") ApiResponse<EmergencyCategory> update(@PathVariable Long id,@Valid @RequestBody CategoryRequest request){User actor=AuthController.currentUser(users);if(actor.role!=Role.ADMIN)throw new AccessDeniedException("Admin role required");EmergencyCategory c=categories.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Category not found"));c.name=request.name();return ApiResponse.ok("Category updated",categories.save(c));}
 @DeleteMapping("/{id}") ApiResponse<EmergencyCategory> deactivate(@PathVariable Long id){User actor=AuthController.currentUser(users);if(actor.role!=Role.ADMIN)throw new AccessDeniedException("Admin role required");EmergencyCategory c=categories.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Category not found"));c.active=false;return ApiResponse.ok("Category deactivated",categories.save(c));}
}

@RestController @RequestMapping("/api/emergencies")
class EmergencyController {
 private final Emergencies emergencies;private final Categories categories;private final Users users;private final Histories histories;private final Notifications notifications;private final AuditLogs logs;private final ResponderAssignments assignments;
 EmergencyController(Emergencies e,Categories c,Users u,Histories h,Notifications n,AuditLogs l,ResponderAssignments assignments){emergencies=e;categories=c;users=u;histories=h;notifications=n;logs=l;this.assignments=assignments;}
 @PostMapping ApiResponse<Emergency> create(@Valid @RequestBody EmergencyRequest r){User actor=AuthController.currentUser(users);Emergency e=new Emergency();e.reporter=actor;e.category=categories.findById(r.categoryId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Emergency category not found"));e.title=r.title();e.description=r.description();e.priority=r.priority()==null?Priority.MEDIUM:r.priority();e.peopleAffected=r.peopleAffected();e.address=r.address();e.city=r.city();e.state=r.state();e.postalCode=r.postalCode();e.latitude=r.latitude();e.longitude=r.longitude();e.assistance=r.assistance();e.evidenceFileName=r.evidenceFileName();e=emergencies.save(e);histories.save(new StatusHistory(e,null,e.status,actor,"Emergency reported"));NotificationUtil.notifyRole(Role.COORDINATOR,"New emergency reported",e.title,notifications,users);NotificationUtil.notifyRole(Role.ADMIN,"New emergency reported",e.title,notifications,users);logs.save(new AuditLog(actor,"CREATE","Emergency",e.id.toString(),e.title));return ApiResponse.ok("Emergency created successfully",e);}
 @GetMapping PageView<Emergency> list(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,@RequestParam(required=false) EmergencyStatus status,@RequestParam(required=false) Priority priority){User u=AuthController.currentUser(users);Pageable p=PageRequest.of(Math.max(0,page),Math.min(100,Math.max(1,size)),Sort.by(Sort.Direction.DESC,"createdAt"));if(u.role==Role.CITIZEN)return PageView.from(emergencies.findByReporterId(u.id,p));if(u.role==Role.RESPONDER){List<Emergency> assigned=assignments.findByResponder_User_Id(u.id).stream().map(a->a.emergency).distinct().sorted(Comparator.comparing((Emergency x)->x.createdAt).reversed()).filter(x->status==null||x.status==status).filter(x->priority==null||x.priority==priority).toList();int from=Math.min(page*size,assigned.size()),to=Math.min(from+size,assigned.size());return new PageView<>(assigned.subList(from,to),page,size,assigned.size(),(int)Math.ceil((double)assigned.size()/size));}Page<Emergency> result=emergencies.findAll(p);if(status!=null||priority!=null){List<Emergency> filtered=result.getContent().stream().filter(x->status==null||x.status==status).filter(x->priority==null||x.priority==priority).toList();return new PageView<>(filtered,page,size,filtered.size(),1);}return PageView.from(result);}
 @GetMapping("/my") PageView<Emergency> mine(@RequestParam(defaultValue="0") int page){User u=AuthController.currentUser(users);return PageView.from(emergencies.findByReporterId(u.id,PageRequest.of(Math.max(0,page),20,Sort.by(Sort.Direction.DESC,"createdAt"))));}
 @GetMapping("/{id}") Emergency get(@PathVariable Long id){Emergency e=emergencies.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Emergency not found"));User u=AuthController.currentUser(users);if(u.role==Role.CITIZEN&&!e.reporter.id.equals(u.id))throw new AccessDeniedException("You may only view your own reports");if(u.role==Role.RESPONDER&&assignments.findFirstByEmergencyIdAndResponder_User_IdAndStatusIn(id,u.id,List.of(AssignmentStatus.ASSIGNED,AssignmentStatus.ACCEPTED,AssignmentStatus.IN_PROGRESS,AssignmentStatus.COMPLETED)).isEmpty())throw new AccessDeniedException("No responder assignment for this incident");return e;}
 @PatchMapping("/{id}/status") @Transactional ApiResponse<Emergency> status(@PathVariable Long id,@Valid @RequestBody StatusRequest r){Emergency e=emergencies.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Emergency not found"));User actor=AuthController.currentUser(users);if(actor.role==Role.CITIZEN&&(!e.reporter.id.equals(actor.id)||e.status!=EmergencyStatus.REPORTED||r.status()!=EmergencyStatus.CANCELLED))throw new AccessDeniedException("Not allowed to change this emergency status");if(actor.role==Role.RESPONDER){if(r.status()!=EmergencyStatus.IN_PROGRESS&&r.status()!=EmergencyStatus.RESOLVED)throw new AccessDeniedException("Responders may only update assigned response status");ResponderAssignment a=assignments.findFirstByEmergencyIdAndResponder_User_IdAndStatusIn(id,actor.id,List.of(AssignmentStatus.ACCEPTED,AssignmentStatus.IN_PROGRESS)).orElseThrow(()->new AccessDeniedException("No active responder assignment for this incident"));a.status=r.status()==EmergencyStatus.RESOLVED?AssignmentStatus.COMPLETED:AssignmentStatus.IN_PROGRESS;if(r.status()==EmergencyStatus.RESOLVED){a.completedAt=Instant.now();a.responder.availability=Availability.AVAILABLE;}else if(a.acceptedAt==null)a.acceptedAt=Instant.now();assignments.save(a);}if(actor.role==Role.CITIZEN&&e.status!=EmergencyStatus.REPORTED)throw new IllegalArgumentException("Only unassigned reports can be cancelled");if(actor.role!=Role.CITIZEN&&actor.role!=Role.RESPONDER&&!validTransition(e.status,r.status()))throw new IllegalArgumentException("Invalid emergency status transition: "+e.status+" to "+r.status());EmergencyStatus old=e.status;e.status=r.status();e.updatedAt=Instant.now();emergencies.save(e);histories.save(new StatusHistory(e,old,e.status,actor,r.comment()));logs.save(new AuditLog(actor,"STATUS_CHANGE","Emergency",id.toString(),old+" -> "+e.status));return ApiResponse.ok("Emergency status updated",e);}
 private boolean validTransition(EmergencyStatus old,EmergencyStatus next){return switch(old){case REPORTED->next==EmergencyStatus.UNDER_REVIEW||next==EmergencyStatus.CANCELLED;case UNDER_REVIEW->next==EmergencyStatus.VERIFIED||next==EmergencyStatus.CANCELLED;case VERIFIED->next==EmergencyStatus.ASSIGNED||next==EmergencyStatus.CANCELLED;case ASSIGNED->next==EmergencyStatus.IN_PROGRESS||next==EmergencyStatus.CANCELLED;case IN_PROGRESS->next==EmergencyStatus.RESOLVED;case RESOLVED,CANCELLED->false;};}
 @GetMapping("/{id}/history") List<StatusHistory> history(@PathVariable Long id){Emergency e=emergencies.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Emergency not found"));User u=AuthController.currentUser(users);if(u.role==Role.CITIZEN&&!e.reporter.id.equals(u.id))throw new AccessDeniedException("Not allowed");return histories.findByEmergencyIdOrderByChangedAtAsc(id);}
}

@RestController @RequestMapping("/api")
class CoordinationController {
 private final Users users;private final Emergencies emergencies;private final Responders responders;private final ResponderAssignments assignments;private final Resources resources;private final ResourceAssignments resourceAssignments;private final Shelters shelters;private final Hospitals hospitals;private final Notifications notifications;private final Announcements announcements;private final AuditLogs logs;private final Histories histories;
 CoordinationController(Users u,Emergencies e,Responders r,ResponderAssignments a,Resources res,ResourceAssignments ra,Shelters s,Hospitals h,Notifications n,Announcements an,AuditLogs l,Histories histories){users=u;emergencies=e;responders=r;assignments=a;resources=res;resourceAssignments=ra;shelters=s;hospitals=h;notifications=n;announcements=an;logs=l;this.histories=histories;}
 @GetMapping("/responders") PageView<ResponderProfile> responders(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)Availability availability){User actor=AuthController.currentUser(users);if(actor.role==Role.CITIZEN)throw new AccessDeniedException("Responder directory is restricted");if(actor.role==Role.RESPONDER){ResponderProfile self=responders.findByUserId(actor.id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Responder profile not found"));return new PageView<>(List.of(self),0,1,1,1);}Page<ResponderProfile> p=responders.findAll(PageRequest.of(Math.max(0,page),Math.min(100,Math.max(size,1))));if(availability==null)return PageView.from(p);List<ResponderProfile> f=p.getContent().stream().filter(x->x.availability==availability).toList();return new PageView<>(f,page,size,f.size(),1);}
 @PostMapping("/responders/profile") @Transactional ApiResponse<ResponderProfile> profile(@Valid @RequestBody ResponderRequest r){User u=AuthController.currentUser(users);if(u.role!=Role.RESPONDER)throw new AccessDeniedException("Responder account required");ResponderProfile p=responders.findByUserId(u.id).orElseGet(ResponderProfile::new);p.user=u;p.skills=r.skills();p.experience=r.experience();p.availability=r.availability()==null?Availability.OFFLINE:r.availability();p.latitude=r.latitude();p.longitude=r.longitude();return ApiResponse.ok("Responder profile saved",responders.save(p));}
 @PatchMapping("/responders/{id}/availability") ApiResponse<ResponderProfile> availability(@PathVariable Long id,@RequestParam Availability value){ResponderProfile p=responders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Responder not found"));User u=AuthController.currentUser(users);if(u.role==Role.RESPONDER&&!p.user.id.equals(u.id))throw new AccessDeniedException("Not allowed");p.availability=value;return ApiResponse.ok("Availability updated",responders.save(p));}
 @PatchMapping("/responders/{id}/verification") ApiResponse<ResponderProfile> verifyResponder(@PathVariable Long id,@RequestParam Verification value){User actor=requireCoordinator();ResponderProfile p=responders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Responder not found"));p.verification=value;ResponderProfile saved=responders.save(p);logs.save(new AuditLog(actor,"VERIFY","ResponderProfile",id.toString(),value.name()));return ApiResponse.ok("Responder verification updated",saved);}
 @GetMapping("/assignments") List<ResponderAssignment> myAssignments(){User u=AuthController.currentUser(users);if(u.role==Role.RESPONDER)return assignments.findByResponder_User_Id(u.id);if(u.role==Role.CITIZEN)throw new AccessDeniedException("Not allowed");return assignments.findAll();}
 @PostMapping("/assignments") @Transactional ApiResponse<ResponderAssignment> assign(@Valid @RequestBody AssignResponderRequest r){User actor=requireCoordinator();Emergency e=emergencies.findById(r.emergencyId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Emergency not found"));if(e.status!=EmergencyStatus.VERIFIED&&e.status!=EmergencyStatus.ASSIGNED)throw new IllegalArgumentException("Incident must be verified before responder assignment");ResponderProfile p=responders.findById(r.responderProfileId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Responder not found"));if(p.verification!=Verification.VERIFIED||p.availability!=Availability.AVAILABLE)throw new IllegalArgumentException("Responder must be verified and available");ResponderAssignment a=new ResponderAssignment();a.emergency=e;a.responder=p;a.assignedBy=actor;a.notes=r.notes();a=assignments.save(a);p.availability=Availability.BUSY;responders.save(p);EmergencyStatus oldEmergencyStatus=e.status;e.status=EmergencyStatus.ASSIGNED;emergencies.save(e);histories.save(new StatusHistory(e,oldEmergencyStatus,e.status,actor,"Responder assigned"));notifications.save(new Notification(p.user,"New response assignment",e.title,"ASSIGNMENT"));logs.save(new AuditLog(actor,"ASSIGN","ResponderAssignment",a.id.toString(),e.title));return ApiResponse.ok("Responder assigned",a);}
 @PatchMapping("/assignments/{id}/status") @Transactional ApiResponse<ResponderAssignment> assignmentStatus(@PathVariable Long id,@Valid @RequestBody AssignmentStatusRequest r){ResponderAssignment a=assignments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Assignment not found"));User actor=AuthController.currentUser(users);if(actor.role==Role.RESPONDER&&!actor.id.equals(a.responder.user.id))throw new AccessDeniedException("Not your assignment");if(actor.role==Role.CITIZEN)throw new AccessDeniedException("Not allowed");EmergencyStatus previousEmergencyStatus=a.emergency.status;if(actor.role==Role.RESPONDER&&!((a.status==AssignmentStatus.ASSIGNED&&(r.status()==AssignmentStatus.ACCEPTED||r.status()==AssignmentStatus.REJECTED))||(a.status==AssignmentStatus.ACCEPTED&&r.status()==AssignmentStatus.IN_PROGRESS)||(a.status==AssignmentStatus.IN_PROGRESS&&r.status()==AssignmentStatus.COMPLETED)))throw new IllegalArgumentException("Invalid assignment status transition");a.status=r.status();a.notes=r.notes();if(r.status()==AssignmentStatus.ACCEPTED)a.acceptedAt=Instant.now();if(r.status()==AssignmentStatus.REJECTED||r.status()==AssignmentStatus.COMPLETED){a.completedAt=r.status()==AssignmentStatus.COMPLETED?Instant.now():null;a.responder.availability=Availability.AVAILABLE;responders.save(a.responder);}if(r.status()==AssignmentStatus.IN_PROGRESS)a.emergency.status=EmergencyStatus.IN_PROGRESS;if(r.status()==AssignmentStatus.COMPLETED)a.emergency.status=EmergencyStatus.RESOLVED;if(a.emergency.status!=previousEmergencyStatus){a.emergency.updatedAt=Instant.now();emergencies.save(a.emergency);histories.save(new StatusHistory(a.emergency,previousEmergencyStatus,a.emergency.status,actor,"Responder assignment updated"));}assignments.save(a);notifications.save(new Notification(a.assignedBy,"Assignment updated",a.status.toString(),"ASSIGNMENT"));return ApiResponse.ok("Assignment updated",a);}
 @PostMapping("/resources") ApiResponse<Resource> createResource(@Valid @RequestBody ResourceRequest r){User actor=requireCoordinator();Resource x=new Resource();x.name=r.name();x.category=r.category();x.description=r.description();x.quantity=r.quantity();x.availableQuantity=r.quantity();x.unit=r.unit();x.location=r.location();x.status=resourceStatus(x);x=resources.save(x);logs.save(new AuditLog(actor,"CREATE","Resource",x.id.toString(),x.name));return ApiResponse.ok("Resource created",x);}
 @GetMapping("/resources") PageView<Resource> resourceList(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return PageView.from(resources.findByActiveTrue(PageRequest.of(Math.max(0,page),Math.min(100,Math.max(1,size)))));}
 @PutMapping("/resources/{id}") @Transactional ApiResponse<Resource> editResource(@PathVariable Long id,@Valid @RequestBody ResourceRequest r){requireCoordinator();Resource x=resources.findByIdForUpdate(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Resource not found"));int used=x.quantity-x.availableQuantity;if(r.quantity()<used)throw new IllegalArgumentException("Quantity cannot be lower than resources already assigned");x.name=r.name();x.category=r.category();x.description=r.description();x.quantity=r.quantity();x.availableQuantity=r.quantity()-used;x.unit=r.unit();x.location=r.location();x.status=resourceStatus(x);x.updatedAt=Instant.now();return ApiResponse.ok("Resource updated",resources.save(x));}
 @DeleteMapping("/resources/{id}") @Transactional ApiResponse<Resource> deleteResource(@PathVariable Long id){requireCoordinator();Resource r=resources.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Resource not found"));r.active=false;r.status=ResourceStatus.UNAVAILABLE;return ApiResponse.ok("Resource deactivated",resources.save(r));}
 @PostMapping("/resources/{id}/assign") @Transactional ApiResponse<ResourceAssignment> assignResource(@PathVariable Long id,@Valid @RequestBody AssignResourceRequest req){User actor=requireCoordinator();Resource r=resources.findByIdForUpdate(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Resource not found"));Emergency e=emergencies.findById(req.emergencyId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Emergency not found"));if(e.status!=EmergencyStatus.VERIFIED&&e.status!=EmergencyStatus.ASSIGNED&&e.status!=EmergencyStatus.IN_PROGRESS)throw new IllegalArgumentException("Incident must be verified before resource assignment");if(req.quantity()>r.availableQuantity)throw new IllegalArgumentException("Insufficient available quantity");r.availableQuantity-=req.quantity();r.status=resourceStatus(r);r.updatedAt=Instant.now();resources.save(r);ResourceAssignment a=new ResourceAssignment();a.resource=r;a.emergency=e;a.assignedBy=actor;a.quantity=req.quantity();a.notes=req.notes();a=resourceAssignments.save(a);logs.save(new AuditLog(actor,"ASSIGN","ResourceAssignment",a.id.toString(),r.name));return ApiResponse.ok("Resource assigned",a);}
 @GetMapping("/resource-assignments") List<ResourceAssignment> resourceAssignmentList(){requireCoordinator();return resourceAssignments.findAll();}
 @PatchMapping("/resource-assignments/{id}/return") @Transactional ApiResponse<ResourceAssignment> returnResource(@PathVariable Long id,@RequestParam @Min(0) int quantity){requireCoordinator();ResourceAssignment a=resourceAssignments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Assignment not found"));int delta=quantity-a.returnedQuantity;if(quantity>a.quantity||delta<0)throw new IllegalArgumentException("Returned quantity must be between previously returned and assigned quantity");a.returnedQuantity=quantity;if(quantity==a.quantity)a.status=AssignmentStatus.RETURNED;Resource r=a.resource;r.availableQuantity+=delta;r.status=resourceStatus(r);resources.save(r);return ApiResponse.ok("Resource return recorded",resourceAssignments.save(a));}
 @PostMapping("/shelters") ApiResponse<Shelter> createShelter(@Valid @RequestBody ShelterRequest r){requireCoordinator();if(r.occupiedCapacity()>r.capacity())throw new IllegalArgumentException("Occupied capacity cannot exceed total capacity");Shelter s=new Shelter();setShelter(s,r);return ApiResponse.ok("Shelter created",shelters.save(s));}
 @PutMapping("/shelters/{id}") ApiResponse<Shelter> updateShelter(@PathVariable Long id,@Valid @RequestBody ShelterRequest r){requireCoordinator();if(r.occupiedCapacity()>r.capacity())throw new IllegalArgumentException("Occupied capacity cannot exceed total capacity");Shelter s=shelters.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Shelter not found"));setShelter(s,r);return ApiResponse.ok("Shelter updated",shelters.save(s));}
 private void setShelter(Shelter s,ShelterRequest r){s.name=r.name();s.address=r.address();s.city=r.city();s.state=r.state();s.contactNumber=r.contactNumber();s.latitude=r.latitude();s.longitude=r.longitude();s.capacity=r.capacity();s.occupiedCapacity=r.occupiedCapacity();s.facilities=r.facilities();s.accessibility=r.accessibility();s.status=r.occupiedCapacity()==r.capacity()?FacilityStatus.FULL:r.status()==null?FacilityStatus.OPEN:r.status();}
 @GetMapping("/shelters") List<Shelter> shelterList(){return shelters.findAll();}
 @GetMapping("/shelters/available") List<Shelter> availableShelters(){return shelters.findByStatus(FacilityStatus.OPEN).stream().filter(x->x.capacity>x.occupiedCapacity).toList();}
 @PostMapping("/hospitals") ApiResponse<Hospital> createHospital(@Valid @RequestBody HospitalRequest r){requireCoordinator();if(r.availableBeds()>r.bedCapacity())throw new IllegalArgumentException("Available beds cannot exceed bed capacity");Hospital h=new Hospital();setHospital(h,r);return ApiResponse.ok("Hospital created",hospitals.save(h));}
 @PutMapping("/hospitals/{id}") ApiResponse<Hospital> updateHospital(@PathVariable Long id,@Valid @RequestBody HospitalRequest r){requireCoordinator();if(r.availableBeds()>r.bedCapacity())throw new IllegalArgumentException("Available beds cannot exceed bed capacity");Hospital h=hospitals.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Hospital not found"));setHospital(h,r);return ApiResponse.ok("Hospital updated",hospitals.save(h));}
 private void setHospital(Hospital h,HospitalRequest r){h.name=r.name();h.address=r.address();h.city=r.city();h.phone=r.phone();h.latitude=r.latitude();h.longitude=r.longitude();h.emergencyAvailable=r.emergencyAvailable();h.bedCapacity=r.bedCapacity();h.availableBeds=r.availableBeds();h.ambulanceAvailable=r.ambulanceAvailable();h.services=r.services();h.status=r.status()==null?FacilityStatus.OPEN:r.status();}
 @GetMapping("/hospitals") List<Hospital> hospitalList(){return hospitals.findAll();}
 @GetMapping("/hospitals/available") List<Hospital> availableHospitals(){return hospitals.findByEmergencyAvailableTrueAndStatus(FacilityStatus.OPEN);}
 @GetMapping("/notifications") PageView<Notification> myNotifications(@RequestParam(defaultValue="0")int page){User u=AuthController.currentUser(users);return PageView.from(notifications.findByUserIdOrderByCreatedAtDesc(u.id,PageRequest.of(Math.max(0,page),25)));}
 @PatchMapping("/notifications/{id}/read") ApiResponse<Notification> markRead(@PathVariable Long id){User u=AuthController.currentUser(users);Notification n=notifications.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Notification not found"));if(!n.user.id.equals(u.id))throw new AccessDeniedException("Not your notification");n.readAt=Instant.now();return ApiResponse.ok("Notification marked read",notifications.save(n));}
 @GetMapping("/announcements/active") List<Announcement> activeAnnouncements(){return announcements.findByActiveTrueAndExpiryAtAfterOrActiveTrueAndExpiryAtIsNullOrderByCreatedAtDesc(Instant.now());}
 @PostMapping("/announcements") ApiResponse<Announcement> createAnnouncement(@Valid @RequestBody AnnouncementRequest r){User actor=requireCoordinator();Announcement a=new Announcement();setAnnouncement(a,r);a.createdBy=actor;a=announcements.save(a);for(User u:users.findAll())if(a.targetAudience.equals("ALL")||a.targetAudience.equals(u.role.name()+"S")||a.targetAudience.equals(u.role.name()))notifications.save(new Notification(u,a.title,a.message,"ANNOUNCEMENT"));logs.save(new AuditLog(actor,"CREATE","Announcement",a.id.toString(),a.title));return ApiResponse.ok("Announcement published",a);}
 @PutMapping("/announcements/{id}") ApiResponse<Announcement> updateAnnouncement(@PathVariable Long id,@Valid @RequestBody AnnouncementRequest r){User actor=requireCoordinator();Announcement a=announcements.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Announcement not found"));setAnnouncement(a,r);a=announcements.save(a);logs.save(new AuditLog(actor,"UPDATE","Announcement",id.toString(),a.title));return ApiResponse.ok("Announcement updated",a);}
 @DeleteMapping("/announcements/{id}") ApiResponse<Announcement> deactivateAnnouncement(@PathVariable Long id){User actor=requireCoordinator();Announcement a=announcements.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Announcement not found"));a.active=false;a=announcements.save(a);logs.save(new AuditLog(actor,"DEACTIVATE","Announcement",id.toString(),a.title));return ApiResponse.ok("Announcement deactivated",a);}
 @GetMapping("/audit-logs") PageView<AuditLog> audit(@RequestParam(defaultValue="0")int page){requireAdmin();return PageView.from(logs.findAllByOrderByCreatedAtDesc(PageRequest.of(Math.max(0,page),50)));}
 @GetMapping("/dashboard/summary") Map<String,Object> summary(){requireCoordinator();List<Emergency> es=emergencies.findAll();return Map.of("emergencies",es.size(),"activeEmergencies",es.stream().filter(x->!List.of(EmergencyStatus.RESOLVED,EmergencyStatus.CANCELLED).contains(x.status)).count(),"criticalEmergencies",es.stream().filter(x->x.priority==Priority.CRITICAL).count(),"availableResponders",responders.findByVerificationAndAvailability(Verification.VERIFIED,Availability.AVAILABLE).size(),"resources",resources.count(),"shelters",shelters.count(),"hospitals",hospitals.count());}
 private void setAnnouncement(Announcement a,AnnouncementRequest r){a.title=r.title();a.message=r.message();a.priority=r.priority()==null?Priority.MEDIUM:r.priority();a.targetAudience=r.targetAudience()==null?"ALL":r.targetAudience();a.expiryAt=r.expiryAt();a.active=r.active()==null||r.active();}
 private User requireCoordinator(){User u=AuthController.currentUser(users);if(u.role!=Role.ADMIN&&u.role!=Role.COORDINATOR)throw new AccessDeniedException("Coordinator role required");return u;}
 private User requireAdmin(){User u=AuthController.currentUser(users);if(u.role!=Role.ADMIN)throw new AccessDeniedException("Admin role required");return u;}
 private static ResourceStatus resourceStatus(Resource r){return r.availableQuantity==0?ResourceStatus.OUT_OF_STOCK:r.availableQuantity<=Math.max(1,r.quantity/5)?ResourceStatus.LOW_STOCK:ResourceStatus.AVAILABLE;}
}

@RestController @RequestMapping("/api")
class UploadController {
 private final org.springframework.core.env.Environment env;
 UploadController(org.springframework.core.env.Environment env){this.env=env;}
 @PostMapping(value="/emergencies/evidence",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) ApiResponse<String> upload(@RequestParam("file") MultipartFile file)throws IOException{if(file.isEmpty()||file.getSize()>5*1024*1024)throw new IllegalArgumentException("File must be non-empty and at most 5 MB");String type=Optional.ofNullable(file.getContentType()).orElse("");byte[] bytes=file.getBytes();boolean valid=switch(type){case "image/jpeg"->bytes.length>3&&(bytes[0]&255)==255&&(bytes[1]&255)==216&&(bytes[2]&255)==255;case "image/png"->bytes.length>8&&(bytes[0]&255)==137&&bytes[1]=='P'&&bytes[2]=='N'&&bytes[3]=='G';case "image/webp"->bytes.length>12&&new String(bytes,0,4,java.nio.charset.StandardCharsets.US_ASCII).equals("RIFF")&&new String(bytes,8,4,java.nio.charset.StandardCharsets.US_ASCII).equals("WEBP");default->false;};if(!valid)throw new IllegalArgumentException("Select a valid JPEG, PNG or WEBP image");String ext=switch(type){case "image/jpeg"->".jpg";case "image/png"->".png";default->".webp";};Path dir=Path.of(env.getProperty("lercs.upload-dir","./uploads")).toAbsolutePath().normalize();Files.createDirectories(dir);String name=UUID.randomUUID()+ext;Path target=dir.resolve(name).normalize();if(!target.startsWith(dir))throw new IllegalArgumentException("Invalid upload path");Files.write(target,bytes,StandardOpenOption.CREATE_NEW);return ApiResponse.ok("Evidence uploaded",name);}
}

class NotificationUtil { static void notifyRole(Role role,String title,String message,Notifications repo,Users users){for(User u:users.findAll())if(u.role==role&&u.active)repo.save(new Notification(u,title,message,"EMERGENCY"));} }
